insert into public.notices (id, title, body, audience, priority, published_on, created_at) values
  ('d0c00015-0000-4000-8000-000000000001', 'Free cardiac screening camp this Sunday', 'DC Hospital is organising a free ECG and BP screening camp from 9 AM to 2 PM at the main lobby. Please inform your patients.', 'all', 'important', (current_date + -1), ((current_date + -1) + time '09:00')),
  ('d0c00015-0000-4000-8000-000000000002', 'NABH audit preparation', 'All departments must update SOP documentation and infection control logs before the audit next week.', 'staff', 'urgent', (current_date + -2), ((current_date + -2) + time '10:00')),
  ('d0c00015-0000-4000-8000-000000000003', 'New MRI 3T machine operational', 'Radiology has commissioned a new 3 Tesla MRI. Slots can now be booked through the front desk.', 'all', 'normal', (current_date + -6), ((current_date + -6) + time '12:00')),
  ('d0c00015-0000-4000-8000-000000000004', 'CME: Updates in diabetes management', 'Continuing medical education session by Dr. Pooja Bansal on Friday, 4 PM, Conference Hall B.', 'doctors', 'normal', (current_date + -4), ((current_date + -4) + time '15:00')),
  ('d0c00015-0000-4000-8000-000000000005', 'Online reports now available', 'Patients can now view their lab results, prescriptions and invoices directly from the patient portal.', 'patients', 'normal', (current_date + -8), ((current_date + -8) + time '11:00')),
  ('d0c00015-0000-4000-8000-000000000006', 'Night shift roster updated', 'The revised night shift roster for nursing staff is available with the Head Nurse.', 'staff', 'normal', (current_date + -10), ((current_date + -10) + time '17:00'));
